parameters.jsCode:
// Cal.com's webhook envelope is { triggerEvent, createdAt, payload: {...} }.
// Flatten the parts we need and derive the two join keys, so no downstream node
// has to know Cal's shape.
const body    = $('Cal Webhook').item.json.body ?? $('Cal Webhook').item.json;
const trigger = body.triggerEvent ?? '';
const p       = body.payload ?? {};

// BOOKING_CANCELLED omits metadata (calcom/cal.com#27783), so sessionId is null
// there and the uid is the only usable key. Created/rescheduled do carry it.
const sessionId = p.metadata?.session_id ?? null;

// On a reschedule Cal sends the NEW booking, with the old uid in rescheduleUid /
// rescheduledFromUid. We must match the row on the OLD uid and move it to the new.
const oldUid = p.rescheduleUid ?? p.rescheduledFromUid ?? null;
const newUid = p.uid ?? null;

const status = trigger === 'BOOKING_CANCELLED' ? 'cancelled'
             : trigger === 'BOOKING_REJECTED'  ? 'rejected'
             : (p.status ?? 'accepted').toLowerCase();

const startISO = p.startTime ?? p.start ?? null;
const zone     = $env.MEETING_TIMEZONE || 'Asia/Karachi';
let whenLocal  = '';
if (startISO) {
  const dt = DateTime.fromISO(startISO, { zone: 'utc' });
  if (dt.isValid) {
    const l = dt.setZone(zone);
    whenLocal = l.toFormat("cccc d LLLL yyyy 'at' h:mm a") + ' (' + l.offsetNameShort + ')';
  }
}

const attendee = (p.attendees ?? [])[0] ?? {};

return [{
  json: {
    trigger,
    // matchUid is what we look the row up BY; newUid is what we move it TO.
    matchUid:  oldUid ?? newUid,
    newUid:    oldUid ? newUid : null,
    sessionId,
    status,
    startISO,
    whenLocal,
    meetingUrl: p.meetingUrl ?? p.location ?? '',
    attendeeName:  attendee.name  ?? p.responses?.name?.value  ?? '',
    attendeeEmail: attendee.email ?? p.responses?.email?.value ?? '',
    title: p.title ?? 'Meeting',
    cancellationReason: p.cancellationReason ?? '',
    isCancel: trigger === 'BOOKING_CANCELLED' || trigger === 'BOOKING_REJECTED',
  },
}];

parameters.jsonBody:
={{ JSON.stringify({
  p_cal_booking_uid: $json.matchUid,
  p_session_id: $json.sessionId,
  p_new_cal_booking_uid: $json.newUid,
  p_cal_booking_status: $json.status,
  p_meeting_start_at: $json.startISO,
  p_cal_meeting_url: $json.meetingUrl,
  p_meeting_booked: !$json.isCancel,
}) }}

