// apply_cal_booking_event returns the matched row, or [] when the booking was
// made straight from the public Cal.com page by someone who never used the chat
// agent. That is an ordinary outcome, so stop quietly instead of erroring.
const rows = $input.first().json;
const row  = Array.isArray(rows) ? rows[0] : rows;
const n    = $('Normalise Cal Event').item.json;

if (!row || !row.session_id) {
  return [];   // unknown booking -> no agent_runs row -> nothing to sync
}

return [{
  json: {
    ...n,
    session_id:  row.session_id,
    crm_lead_id: row.crm_lead_id,
    crm_task_id: row.crm_task_id,
    // Prefer the name/email already on the run; the Cal payload can carry a
    // different attendee than the visitor who started the conversation.
    visitorName:  row.visitor_name  || n.attendeeName  || 'there',
    visitorEmail: row.visitor_email || n.attendeeEmail || '',
    hasTask: Boolean(row.crm_task_id),
  },
}];

const res = $input.first().json;
const raw = res.headers?.['set-cookie'] ?? [];
const list = Array.isArray(raw) ? raw : [raw];
const jar = {};
for (const entry of list) {
  const [pair] = String(entry).split(';');
  const eq = pair.indexOf('=');
  if (eq === -1) continue;
  jar[pair.slice(0, eq).trim()] = pair.slice(eq + 1).trim();
}
if (!jar.access_token) throw new Error('AutoCRM login returned no access_token cookie.');
return [{ json: {
  cookieHeader: `access_token=${jar.access_token}; csrf_token=${jar.csrf_token ?? ''}`,
  csrfToken: jar.csrf_token ?? '',
} }];

parameters.jsonBody:
