  status: 'canceled',
  description: 'Meeting CANCELLED on Cal.com.'
    + ($('Resolve Run').item.json.cancellationReason
        ? '\nReason: ' + $('Resolve Run').item.json.cancellationReason : ''),
} : {
  due_at: $('Resolve Run').item.json.startISO,
  description: 'Meeting RESCHEDULED on Cal.com.\n\nNew time: '
    + $('Resolve Run').item.json.whenLocal
    + '\nJoin: ' + $('Resolve Run').item.json.meetingUrl,
}) }}

